import{_ as o,c as t,o as d,ah as r}from"./chunks/framework.DX1DJjtl.js";const u=JSON.parse('{"title":"Dropdown","description":"","frontmatter":{},"headers":[],"relativePath":"api/elements/Dropdown.md","filePath":"api/elements/Dropdown.md","lastUpdated":1785349141000}'),n={name:"api/elements/Dropdown.md"};function l(a,e,s,i,c,p){return d(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="dropdown" tabindex="-1">Dropdown <a class="header-anchor" href="#dropdown" aria-label="Permalink to &quot;Dropdown&quot;">​</a></h1><p><em>extends Collection</em></p><p>Dropdown: collapsed selection row that expands to an item list. Fires &quot;select&quot;; closes on selection, on toggle, or when focus moves away.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>text</td><td><code>any</code></td><td><code>&quot;Select...&quot;</code></td><td>placeholder while nothing is selected</td></tr><tr><td>dropHeight</td><td><code>number</code></td><td><code>6</code></td><td>maximum visible list rows</td></tr><tr><td>offset</td><td><code>number</code></td><td><code>0</code></td><td>list scroll offset</td></tr><tr><td>background</td><td><code>number|false</code></td><td><code>colors.gray</code></td><td>Background color (false = transparent)</td></tr><tr><td>dropBackground</td><td><code>number</code></td><td><code>colors.black</code></td><td>open list background</td></tr><tr><td>width</td><td><code>number</code></td><td><code>14</code></td><td>Width in terminal cells</td></tr><tr><td>scrollbar</td><td><code>ItemViewScrollbarMode</code></td><td><code>&quot;auto&quot;</code></td><td>&quot;auto&quot;, &quot;always&quot; or &quot;hidden&quot;</td></tr><tr><td>scrollbarColor</td><td><code>number</code></td><td><code>colors.gray</code></td><td>Scrollbar track color</td></tr><tr><td>scrollbarThumbColor</td><td><code>number</code></td><td><code>colors.lightGray</code></td><td>Scrollbar thumb color</td></tr><tr><td>height</td><td><code>number</code></td><td><em>dynamic</em></td><td>Follows the open state; setting it explicitly breaks expansion</td></tr><tr><td>open</td><td><code>boolean</code></td><td><code>false</code></td><td>Whether the list is expanded; the element floats above siblings while open</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="dropdown-getscrollinfo" tabindex="-1">Dropdown:getScrollInfo() <a class="header-anchor" href="#dropdown-getscrollinfo" aria-label="Permalink to &quot;Dropdown:getScrollInfo()&quot;">​</a></h3><p>Returns the scrollbar geometry of the open list.</p><ul><li><strong>returns</strong> <strong>geometry</strong> (<code>ItemViewGeometry</code>) The itemview geometry</li></ul><h3 id="dropdown-setoffset-offset" tabindex="-1">Dropdown:setOffset(offset) <a class="header-anchor" href="#dropdown-setoffset-offset" aria-label="Permalink to &quot;Dropdown:setOffset(offset)&quot;">​</a></h3><p>Scrolls the open list to an absolute offset (clamped).</p><ul><li><p><strong>offset</strong> (<code>number</code>) Items scrolled past above the viewport</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="dropdown-scrolltoitem-index" tabindex="-1">Dropdown:scrollToItem(index) <a class="header-anchor" href="#dropdown-scrolltoitem-index" aria-label="Permalink to &quot;Dropdown:scrollToItem(index)&quot;">​</a></h3><p>Scrolls the given item index into the visible list area.</p><ul><li><p><strong>index</strong> (<code>number</code>) The item index to make visible</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="dropdown-select-index-emit" tabindex="-1">Dropdown:select(index, emit) <a class="header-anchor" href="#dropdown-select-index-emit" aria-label="Permalink to &quot;Dropdown:select(index, emit)&quot;">​</a></h3><p>Selects an item, closes the list and fires the select event.</p><ul><li><p><strong>index</strong> (<code>integer</code>) The item index to select</p></li><li><p><strong>emit</strong> (<code>boolean</code>, optional) false suppresses the select event</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="dropdown-setup" tabindex="-1">Dropdown:setup() <a class="header-anchor" href="#dropdown-setup" aria-label="Permalink to &quot;Dropdown:setup()&quot;">​</a></h3><p>Initializes per-instance state and input handlers.</p><h3 id="dropdown-clear" tabindex="-1">Dropdown:clear() <a class="header-anchor" href="#dropdown-clear" aria-label="Permalink to &quot;Dropdown:clear()&quot;">​</a></h3><p>Removes all entries and resets selection, scroll and open state.</p><ul><li><strong>returns</strong> (<code>self</code>)</li></ul><h3 id="dropdown-removeitem-index" tabindex="-1">Dropdown:removeItem(index) <a class="header-anchor" href="#dropdown-removeitem-index" aria-label="Permalink to &quot;Dropdown:removeItem(index)&quot;">​</a></h3><p>Removes an entry and clamps the dropdown scroll offset.</p><ul><li><p><strong>index</strong> (<code>integer|CollectionEntry</code>) Item index or entry</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="dropdown-handlemouse-event-btn-x-y" tabindex="-1">Dropdown:handleMouse(event, btn, x, y) <a class="header-anchor" href="#dropdown-handlemouse-event-btn-x-y" aria-label="Permalink to &quot;Dropdown:handleMouse(event, btn, x, y)&quot;">​</a></h3><p>Routes mouse input in local coordinates (wheel scrolling etc.).</p><ul><li><p><strong>event</strong> (<code>string</code>) The mouse event name</p></li><li><p><strong>btn</strong> (<code>number</code>) Button or scroll direction</p></li><li><p><strong>x</strong> (<code>number</code>) Local x coordinate</p></li><li><p><strong>y</strong> (<code>number</code>) Local y coordinate</p></li><li><p><strong>returns</strong> <strong>consumer</strong> (<code>Element|nil</code>) The consuming element, or nil to pass through</p></li></ul><h3 id="dropdown-handlekey-event-a-b" tabindex="-1">Dropdown:handleKey(event, a, b) <a class="header-anchor" href="#dropdown-handlekey-event-a-b" aria-label="Permalink to &quot;Dropdown:handleKey(event, a, b)&quot;">​</a></h3><p>Handles keyboard input while focused.</p><ul><li><strong>event</strong> (<code>string</code>) The key event name (key, key_up, char, paste)</li><li><strong>a</strong> (<code>any</code>) Key code or typed text</li><li><strong>b</strong> (<code>any</code>, optional) Secondary key-event value</li></ul><h3 id="dropdown-render-buf" tabindex="-1">Dropdown:render(buf) <a class="header-anchor" href="#dropdown-render-buf" aria-label="Permalink to &quot;Dropdown:render(buf)&quot;">​</a></h3><p>Renders the element into the buffer.</p><ul><li><strong>buf</strong> (<code>Render</code>) The render buffer (local coordinates, pre-clipped)</li></ul>',35)])])}const m=o(n,[["render",l]]);export{u as __pageData,m as default};
